  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$minTrimDieCostWithMaterial$str$, $str$3000$str$, $str$Currency$str$, $str$Threshold below which the material based calculation of the trimming die cost is not valid.$str$, $jsonb${"Variable Name":"minTrimDieCostWithMaterial","String Value":3000,"Unit Type Name":"Currency","Notes":"Threshold below which the material based calculation of the trimming die cost is not valid.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
