  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$multLengthElongationFactor$str$, $str$1.61$str$, NULL, $str$A factor that represents the elongation in mult length across the forging sequence. A maximum value of 10% is assumed for length elongation in a single stage with a maximum of 5 stages assumed. Used in valid stock selection to determine the minimum mult length.$str$, $jsonb${"Variable Name":"multLengthElongationFactor","String Value":1.61,"Unit Type Name":null,"Notes":"A factor that represents the elongation in mult length across the forging sequence. A maximum value of 10% is assumed for length elongation in a single stage with a maximum of 5 stages assumed. Used in valid stock selection to determine the minimum mult length.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$numTemperatureIntervals$str$, $str$100$str$, NULL, $str$The number of temperature intervals used when calculating the Reheat time. Increasing this value increases accuracy and computation time. Set to any integer value greater than 0.$str$, $jsonb${"Variable Name":"numTemperatureIntervals","String Value":100,"Unit Type Name":null,"Notes":"The number of temperature intervals used when calculating the Reheat time. Increasing this value increases accuracy and computation time. Set to any integer value greater than 0.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$openDiePressCalibrationTime$str$, $str$60$str$, $str$Time$str$, $str$The time spent calibrating the location of the mult on the Open Die machine. Used to calculate the cycle time for the Open Die Press process.$str$, $jsonb${"Variable Name":"openDiePressCalibrationTime","String Value":60,"Unit Type Name":"Time","Notes":"The time spent calibrating the location of the mult on the Open Die machine. Used to calculate the cycle time for the Open Die Press process.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$ovenPartSpacingFactor$str$, $str$0.50$str$, NULL, $str$Factor applied to determine the minimum part spacing required in the oven. For Reheat it is applied to the preformed stock's diameter / width. Set to any value greater than or equal to 0.$str$, $jsonb${"Variable Name":"ovenPartSpacingFactor","String Value":0.5,"Unit Type Name":null,"Notes":"Factor applied to determine the minimum part spacing required in the oven. For Reheat it is applied to the preformed stock's diameter / width. Set to any value greater than or equal to 0.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$ovenTemperatureOffset$str$, $str$100$str$, $str$Temperature$str$, $str$Temperature offset used to calculate the minimum oven temperature required to heat the selected material to its forging temperature. Set to any value greater than 0.$str$, $jsonb${"Variable Name":"ovenTemperatureOffset","String Value":100,"Unit Type Name":"Temperature","Notes":"Temperature offset used to calculate the minimum oven temperature required to heat the selected material to its forging temperature. Set to any value greater than 0.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$overheadRateAdjustmentFactor$str$, $str$1$str$, NULL, $str$Factor used to globally increase or decrease overhead rate per process.$str$, $jsonb${"Variable Name":"overheadRateAdjustmentFactor","String Value":1,"Unit Type Name":null,"Notes":"Factor used to globally increase or decrease overhead rate per process.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$partLongitudinalRatioThreshold$str$, $str$2$str$, NULL, $str$The threshold ratio between the largest and next largest part box dimensions. If greater than this value, the part is classified as longitudinal. This will influence process selection.$str$, $jsonb${"Variable Name":"partLongitudinalRatioThreshold","String Value":2,"Unit Type Name":null,"Notes":"The threshold ratio between the largest and next largest part box dimensions. If greater than this value, the part is classified as longitudinal. This will influence process selection.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
