  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$planeDeviationIsBentMinThreshold$str$, $str$0.33$str$, NULL, $str$The minimum normalized plane deviation on a Cross Sectional Analysis GCD that classifies the part as being bent in the plane direction.$str$, $jsonb${"Variable Name":"planeDeviationIsBentMinThreshold","String Value":0.33,"Unit Type Name":null,"Notes":"The minimum normalized plane deviation on a Cross Sectional Analysis GCD that classifies the part as being bent in the plane direction.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$planeDeviationLineOfSymmetryMaxThreshold$str$, $str$0.12$str$, NULL, $str$The maximum normalized plane deviation on a Cross Sectional Analysis GCD that classifies the part as having a line of symmetry.$str$, $jsonb${"Variable Name":"planeDeviationLineOfSymmetryMaxThreshold","String Value":0.12,"Unit Type Name":null,"Notes":"The maximum normalized plane deviation on a Cross Sectional Analysis GCD that classifies the part as having a line of symmetry.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$preformPunchDepthFactor$str$, $str$0.60$str$, NULL, $str$Factor applied to the depth of a hole to calculate its punched depth before it is pierced. Used to calculate the punching force required in the Open Die Press process.$str$, $jsonb${"Variable Name":"preformPunchDepthFactor","String Value":0.6,"Unit Type Name":null,"Notes":"Factor applied to the depth of a hole to calculate its punched depth before it is pierced. Used to calculate the punching force required in the Open Die Press process.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$preheatFurnaceGasType$str$, $str$Natural Gas$str$, NULL, $str$The type of fuel gas that is supplied to the burners in the Preheat Furnace.$str$, $jsonb${"Variable Name":"preheatFurnaceGasType","String Value":"Natural Gas","Unit Type Name":null,"Notes":"The type of fuel gas that is supplied to the burners in the Preheat Furnace.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$preheatInitialTemperature$str$, $str$16$str$, $str$Temperature$str$, $str$Ambient temperature in a factory used to calculate the initial temperature of the stock prior to heating it.$str$, $jsonb${"Variable Name":"preheatInitialTemperature","String Value":16,"Unit Type Name":"Temperature","Notes":"Ambient temperature in a factory used to calculate the initial temperature of the stock prior to heating it.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$pressToolLifeNumberOfParts$str$, $str$7500$str$, NULL, $str$The number of parts that can be produced from each Press tool before the tooling needs refurbishing or replacing.$str$, $jsonb${"Variable Name":"pressToolLifeNumberOfParts","String Value":7500,"Unit Type Name":null,"Notes":"The number of parts that can be produced from each Press tool before the tooling needs refurbishing or replacing.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$punchedHoleDiameterToDepthRatio$str$, $str$0.5$str$, NULL, $str$Factor applied to a SimpleHole's depth to calculate the minimum required diameter to enable Punching operations in Open Die Press.$str$, $jsonb${"Variable Name":"punchedHoleDiameterToDepthRatio","String Value":0.5,"Unit Type Name":null,"Notes":"Factor applied to a SimpleHole's depth to calculate the minimum required diameter to enable Punching operations in Open Die Press.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$radiusCoefficientOfVariationThreshold2D$str$, $str$0.25$str$, NULL, $str$The threshold for classifying 2D parts as having a smaller, or larger, coefficient of variation for Cross Sectional Area Radius. Calculated as the standard deviation of the radius divided by the average radius.$str$, $jsonb${"Variable Name":"radiusCoefficientOfVariationThreshold2D","String Value":0.25,"Unit Type Name":null,"Notes":"The threshold for classifying 2D parts as having a smaller, or larger, coefficient of variation for Cross Sectional Area Radius. Calculated as the standard deviation of the radius divided by the average radius.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
