  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$reheatInitialTempFactor$str$, $str$0.50$str$, NULL, $str$Factor applied to the forging temperature of the selected material to calculate the starting temperature when calculating the time to reheat the part. Set to any value between 0.00 and 0.99.$str$, $jsonb${"Variable Name":"reheatInitialTempFactor","String Value":0.5,"Unit Type Name":null,"Notes":"Factor applied to the forging temperature of the selected material to calculate the starting temperature when calculating the time to reheat the part. Set to any value between 0.00 and 0.99.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$ringRollCalibrationTime$str$, $str$60$str$, $str$Time$str$, $str$The time spent calibrating the location of the pre-formed mult on the Ring Rolling machine. Used to calculate the cycle time for the Ring Rolling process.$str$, $jsonb${"Variable Name":"ringRollCalibrationTime","String Value":60,"Unit Type Name":"Time","Notes":"The time spent calibrating the location of the pre-formed mult on the Ring Rolling machine. Used to calculate the cycle time for the Ring Rolling process.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
