  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$scaleLossAllowancePercentage$str$, $str$3$str$, NULL, $str$Material allowance for losses caused by scale formation when heating the mult using a gas furnace, represented as a percentage of the total forged volume (including flash).$str$, $jsonb${"Variable Name":"scaleLossAllowancePercentage","String Value":3,"Unit Type Name":null,"Notes":"Material allowance for losses caused by scale formation when heating the mult using a gas furnace, represented as a percentage of the total forged volume (including flash).","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$scaleLossAllowancePercentageInductionHeating$str$, $str$1$str$, NULL, $str$Material allowance for losses caused by scale formation when heating the mult using induction heating, represented as a percentage of the total forged volume (including flash).$str$, $jsonb${"Variable Name":"scaleLossAllowancePercentageInductionHeating","String Value":1,"Unit Type Name":null,"Notes":"Material allowance for losses caused by scale formation when heating the mult using induction heating, represented as a percentage of the total forged volume (including flash).","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
