  ($str$variable$str$, 'USA', $str$2026-Forging$str$, $str$surfaceAreaThreshold2D$str$, $str$0.95$str$, NULL, $str$A value between 0 and 1 representing the proportion of the part surface area that must be about a turning axis to classify the part as 2D, or axisymmetric.$str$, $jsonb${"Variable Name":"surfaceAreaThreshold2D","String Value":0.95,"Unit Type Name":null,"Notes":"A value between 0 and 1 representing the proportion of the part surface area that must be about a turning axis to classify the part as 2D, or axisymmetric.","Section":"Inherited","Deprecated":"No"}$jsonb$::jsonb),
